import { useEffect, useState } from 'react';
import axios from '../../api/axiosInstance';

const Employees = () => {
    const [employees, setEmployees] = useState([]);
    const [search, setSearch] = useState('');
    const [form, setForm] = useState({
        name: '', email: '', phone: '', position: '', department: '',
        address: '', salary: '', startDate: '', avatar: null
    });
    const [editId, setEditId] = useState(null);

    const fetchEmployees = async () => {
        const res = await axios.get('/employees');
        setEmployees(res.data);
    };

    useEffect(() => { fetchEmployees(); }, []);

    const handleDelete = async (id) => {
        if (window.confirm('Xóa nhân sự này?')) {
            await axios.delete(`/employees/${id}`);
            fetchEmployees();
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const data = new FormData();
        Object.keys(form).forEach(k => {
            if (form[k]) data.append(k, form[k]);
        });

        if (editId) {
            await axios.put(`/employees/${editId}`, data);
            alert('Đã cập nhật!');
        } else {
            await axios.post('/employees', data);
            alert('Đã thêm!');
        }

        fetchEmployees();
        setForm({ name: '', email: '', phone: '', position: '', department: '', address: '', salary: '', startDate: '', avatar: null });
        setEditId(null);
    };

    const handleEdit = (emp) => {
        setForm({
            name: emp.name, email: emp.email, phone: emp.phone,
            position: emp.position, department: emp.department,
            address: emp.address, salary: emp.salary,
            startDate: emp.startDate?.slice(0, 10),
            avatar: null
        });
        setEditId(emp._id);
    };

    return (
        <div>
            <h2>👥 Danh sách Nhân sự</h2>

            <input
                type="text"
                placeholder="Tìm kiếm..."
                onChange={(e) => setSearch(e.target.value)}
                style={{ marginBottom: '10px', padding: '8px', width: '300px' }}
            />

            <table border="1" cellPadding="10" width="100%">
                <thead>
                    <tr>
                        <th>Ảnh</th>
                        <th>Họ tên</th>
                        <th>Email</th>
                        <th>Điện thoại</th>
                        <th>Vị trí</th>
                        <th>Bộ phận</th>
                        <th>Lương</th>
                        <th>Bắt đầu</th>
                        <th>Hành động</th>
                    </tr>
                </thead>
                <tbody>
                    {employees.filter(e => e.name.toLowerCase().includes(search.toLowerCase())).map(emp => (
                        <tr key={emp._id}>
                            <td><img src={emp.avatar} alt="" width="50" /></td>
                            <td>{emp.name}</td>
                            <td>{emp.email}</td>
                            <td>{emp.phone}</td>
                            <td>{emp.position}</td>
                            <td>{emp.department}</td>
                            <td>{emp.salary?.toLocaleString()}đ</td>
                            <td>{emp.startDate?.slice(0, 10)}</td>
                            <td>
                                <button onClick={() => handleEdit(emp)}>✏️</button>
                                <button onClick={() => handleDelete(emp._id)}>🗑️</button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <hr style={{ margin: '40px 0' }} />
            <h3>{editId ? '🛠️ Cập nhật nhân sự' : '➕ Thêm mới nhân sự'}</h3>

            <form onSubmit={handleSubmit} encType="multipart/form-data">
                <input type="text" placeholder="Họ tên" required value={form.name}
                    onChange={e => setForm({ ...form, name: e.target.value })} /><br />

                <input type="email" placeholder="Email" value={form.email}
                    onChange={e => setForm({ ...form, email: e.target.value })} /><br />

                <input type="tel" placeholder="Điện thoại" value={form.phone}
                    onChange={e => setForm({ ...form, phone: e.target.value })} /><br />

                <input type="text" placeholder="Vị trí" value={form.position}
                    onChange={e => setForm({ ...form, position: e.target.value })} /><br />

                <input type="text" placeholder="Bộ phận" value={form.department}
                    onChange={e => setForm({ ...form, department: e.target.value })} /><br />

                <input type="text" placeholder="Địa chỉ" value={form.address}
                    onChange={e => setForm({ ...form, address: e.target.value })} /><br />

                <input type="number" placeholder="Lương" value={form.salary}
                    onChange={e => setForm({ ...form, salary: e.target.value })} /><br />

                <input type="date" value={form.startDate}
                    onChange={e => setForm({ ...form, startDate: e.target.value })} /><br />

                <input type="file" accept="image/*"
                    onChange={e => setForm({ ...form, avatar: e.target.files[0] })} /><br /><br />

                <button type="submit">{editId ? '💾 Lưu cập nhật' : '➕ Thêm mới'}</button>
            </form>
        </div>
    );
};

export default Employees;
